draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // stick figure
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();

  // arms
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2 - 30 + 10 * Math.sin(t), H/2 + 60);
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2 + 30 + 10 * Math.sin(t), H/2 + 60);
  ctx.stroke();

  // legs
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 60);
  ctx.lineTo(W/2 - 20 + 10 * Math.cos(t), H/2 + 100);
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 60);
  ctx.lineTo(W/2 + 20 + 10 * Math.cos(t), H/2 + 100);
  ctx.stroke();

  // book
  ctx.fillStyle = 'black';
  ctx.fillRect(W/2 - 40, H/2 - 80, 80, 20);
  ctx.fillStyle = 'white';
  ctx.font = '14px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('10,000', W/2, H/2 - 60);

  // clock
  ctx.beginPath();
  ctx.arc(W/2 + 80, H/2 - 40, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 80, H/2 - 40);
  ctx.lineTo(W/2 + 80 + 15 * Math.sin(t), H/2 - 40 + 15 * Math.cos(t));
  ctx.stroke();

  ctx.restore();
}
